import{z as i,x as D,o,c,q as s,j as l,D as d,d as t,s as n,S as p,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"树形 DP","description":"","frontmatter":{"title":"树形 DP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tree-dp.md","filePath":"cs/tree-dp.md","lastUpdated":1791063341000}'),E={name:"cs/tree-dp.md"};function A(B,a,m,u,h,P){const r=D("Mermaid");return o(),c("div",null,[a[2]||(a[2]=s('<h1 id="树形-dp" tabindex="-1">树形 DP <a class="header-anchor" href="#树形-dp" aria-label="Permalink to &quot;树形 DP&quot;">​</a></h1><div class="epigraph"><p>无环则子树先算完再合并到父亲；状态常是「选根或不选」「子树背包」，总 $O(n)$ 或 $O(n\\cdot\\text{容量})$。</p><footer>—— 据 CLRS 第 15 章最优子结构；树上 DP 为标准教材技法整理</footer></div><p>上一课<a href="/cs/bitmask-dp">状态压缩 DP</a>在指数子集上。树 \\(n\\) 可达 \\(10^5\\)，状态沿边无环。缺口是树形 DP：先 DFS 后序，把孩子 DP 合并。不重写状压。后课数位 DP 换十进制。与<a href="/cs/centroid-decomposition">点分治</a>分工：一个整棵最优，一个点对统计。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>独立集：<code>dp[u][0/1]</code> 不选/选 \\(u\\)，孩子相应约束。树上背包：子树体积合并，注意循环方向防复用。换根是后课。本课固定根。</p><p>缺口是后序合并，不是生成树 MST。</p><h3 id="合并顺序与背包" tabindex="-1">合并顺序与背包 <a class="header-anchor" href="#合并顺序与背包" aria-label="Permalink to &quot;合并顺序与背包&quot;">​</a></h3><p>多个孩子做背包，\\(O(\\sum sz)\\) 要按子树大小分析，错误的 <code>for v in children for j backwards</code> 复杂度可能 \\(O(n^2)\\)。点名即可。</p><p><span class="marginnote">树独立集线性。树上背包复杂度有精细界。后课换根二次 DFS 把每个点当根。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>DFS：先孩子后自己。状态设计使边只看父子。森林逐棵。</p>',11)),(o(),l(p,null,{default:d(()=>[n(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E5%AD%A9%E5%AD%90%20dp%22%5D%20--%3E%20MER%5B%22%E5%90%88%E5%B9%B6%E5%88%B0%20u%22%5D%0A%20%20MER%20--%3E%20PAR%5B%22%E4%BA%A4%E7%BB%99%E7%88%B6%E4%BA%B2%22%5D%0A"})]),fallback:d(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"叶子边界明确。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"树的最优子结构：最优解在子树上的限制仍最优。与 DAG DP 同，树是特殊 DAG（定根后）。与 HLD：HLD 管路径查询，树 DP 管一次全局最优。",-1)),a[6]||(a[6]=e("p",null,"以最大权独立集为例，看「选 / 不选」两种状态各自怎么从孩子算出来：",-1)),(o(),l(p,null,{default:d(()=>[n(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20KIDS%5B%22%E6%89%80%E6%9C%89%E5%AD%A9%E5%AD%90%20v%20%E7%9A%84%20dp%5Bv%5D%5B0%2F1%5D%5D%20--%3E%20NC%5Bu%20%E4%B8%8D%E9%80%89%3A%20%CE%A3%20max(dp%5Bv%5D%5B0%5D%2C%20dp%5Bv%5D%5B1%5D)%22%5D%0A%20%20KIDS%20--%3E%20SEL%5B%22u%20%E9%80%89%3A%20w%5Bu%5D%20%2B%20%CE%A3%20dp%5Bv%5D%5B0%5D%22%5D%0A%20%20NC%20--%3E%20D0%5B%22dp%5Bu%5D%5B0%5D%22%5D%0A%20%20SEL%20--%3E%20D1%5B%22dp%5Bu%5D%5B1%5D%22%5D%0A%20%20D0%20--%3E%20ANS%5B%22%E6%A0%B9%E5%A4%84%E5%8F%96%20max%20%E5%8D%B3%E7%AD%94%E6%A1%88%22%5D%0A%20%20D1%20--%3E%20ANS%0A"})]),fallback:d(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">直觉类比：后序合并就是「先问完所有孩子，再答父亲」。孩子答完之后父亲的问题只剩一次查表加法——每个点被算一次、被看常数次，所以总时间是 \\(O(n)\\)，与树的形状无关。</span></p><p><span class="marginnote">常见误区：初学者容易以为树形 DP 还要像序列 DP 那样专门设计「转移顺序」。定根之后「孩子先于父亲」就是现成的拓扑序，DFS 的后序位置天然给出这个顺序，不需要再排序或建图。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写换根、不写虚树。有环要先 SCC 或点双。后课默认：树上选/不选、子树背包用后序 DP。下一课数位 DP。</p><p><span class="marginnote">术语翻译：「背包容量倒序循环」= 让本轮用到的旧值 <code>dp[j-w]</code> 还停留在「不含当前孩子」的状态。数字实例：正序走时，\\(w=2\\) 的孩子会把 <code>dp[2]</code> 加进 <code>dp[4]</code>，又把更新过的 <code>dp[4]</code> 加进 <code>dp[6]</code>——同一个孩子被叠选；倒序走 <code>dp[6]</code> 先算，用的还是干净的旧值。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>后序合并孩子；无环是前提。</li><li>独立集线性；背包注意复杂度。</li><li>固定根；换根后课。</li><li>出处：CLRS 第 15 章；树 DP 标准技法。</li></ul>',7))])}const _=i(E,[["render",A]]);export{S as __pageData,_ as default};
